<?php

declare(strict_types=1);

namespace BeyndaCalculator\QuoteApi;

final class ServerPdfFont
{
    /** @return array<string, mixed> */
    public static function metrics(): array
    {
        return json_decode(base64_decode(''), true, 32, JSON_THROW_ON_ERROR);
    }

    public static function bytes(): string
    {
        $data = file_get_contents(__DIR__ . '/assets/DejaVuSans.ttf');
        if (!is_string($data) || $data === '') throw new \RuntimeException('PDF font is unavailable.');
        return $data;
    }
}
